fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();

    // First matrix: each row is a clone of x
    let mut x_mat = Vec::with_capacity(rows);
    for _ in 0..rows {
        // Clone of x is safe and clean
        x_mat.push(x.clone());
    }

    // Second matrix: each row is y[i] repeated cols times
    let mut y_mat = Vec::with_capacity(rows);
    for &y_val in &y {
        let mut row = Vec::with_capacity(cols);
        for _ in 0..cols {
            row.push(y_val);
        }
        y_mat.push(row);
    }

    (x_mat, y_mat)
}